#!/usr/bin/env python3
from pathlib import Path

MANDATORY = Path('scripts/gpw_mandatory_daily.py')
LOCO = Path('scripts/gpw_loco_counterfactual_replay.py')


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly one match, got {count}')
    return text.replace(old, new, 1)


m = MANDATORY.read_text(encoding='utf-8')
m = replace_once(
    m,
    '            enriched = copy.deepcopy(candidate)\n            enriched["opening_confirmation"] = confirmation\n',
    '            enriched = copy.deepcopy(candidate)\n            # Preserve the pre-EV geometry at the exact production decision point.\n            # PR507 uses this only for research replay; it never feeds production.\n            enriched["pre_ev_reward_risk"] = float(\n                candidate.get("reward_risk") or config.get("minimum_reward_risk", 1.5)\n            )\n            enriched["opening_confirmation"] = confirmation\n',
    'mandatory pre-EV capture',
)

needle = '    return payload\n\n\ndef persist(payload: dict[str, Any]) -> None:\n    gpw.validate_payload(payload, require_today=False)\n'
insert = '''    # Exact same-run research source for PR507 LOCO.  Keep it ephemeral in\n    # memory; persist() removes it before writing the public/history payload and\n    # stores it only under data/internal.  This avoids re-fetching a moving\n    # market snapshot after the production decision.\n    quant_names = (\n        "relative_momentum",\n        "volume_liquidity",\n        "market_context",\n        "risk_reward",\n        "historical_expectancy",\n    )\n    payload["_loco_source_state"] = {\n        "schema_version": "gpw-loco-producer-state-v1",\n        "decision_date": payload["date"],\n        "producer_decision_at": payload["generated_at"],\n        "captured_at": now.isoformat(timespec="seconds"),\n        "selection_mode": "MANDATORY_DAILY_FINAL",\n        "producer_selected_symbol": selected.get("symbol"),\n        "producer_selected_score": core.round2(score),\n        "base_weights": {key: float(value) for key, value in (config.get("weights") or {}).items()},\n        "opening_weight": opening_weight,\n        "candidate_errors": copy.deepcopy(candidate_errors),\n        "candidates": [\n            {\n                "symbol": enriched.get("symbol"),\n                "name": enriched.get("name"),\n                "sector": enriched.get("sector"),\n                "quant_rank": enriched.get("quant_rank"),\n                "quant_pre_score": enriched.get("quant_pre_score"),\n                "base_scores": {\n                    "catalyst": neutral_catalyst,\n                    **{name: (enriched.get("scores") or {}).get(name) for name in quant_names},\n                },\n                "legacy_composite_score": enriched.get("legacy_composite_score"),\n                "opening_confirmation_score": (enriched.get("opening_confirmation") or {}).get("score"),\n                "opening_confirmation": copy.deepcopy(enriched.get("opening_confirmation")),\n                "opening_adjusted_score": enriched.get("opening_adjusted_score"),\n                "expected_value_score": (enriched.get("expected_value_model") or {}).get("score"),\n                "expected_value_model": copy.deepcopy(enriched.get("expected_value_model")),\n                "expected_value_weight": enriched.get("expected_value_weight", 0.0),\n                "final_score": enriched.get("ev_adjusted_score"),\n                "pre_ev_reward_risk": enriched.get("pre_ev_reward_risk"),\n                "full_reward_risk": enriched.get("reward_risk"),\n                "risk_percent": enriched.get("risk_percent"),\n                "historical_feature_session": enriched.get("historical_feature_session"),\n                "historical_feature_lag_sessions": enriched.get("historical_feature_lag_sessions"),\n                "execution_data_gate": copy.deepcopy(enriched.get("execution_data_gate")),\n                "market_snapshot": copy.deepcopy(candidate_snapshot),\n            }\n            for enriched, candidate_snapshot in evaluated\n        ],\n        "governance": {\n            "prospective_only": True,\n            "historical_backfill": False,\n            "observational_only": True,\n            "decision_influence": False,\n            "production_trade_writeback": False,\n        },\n    }\n    return payload\n\n\ndef persist(payload: dict[str, Any]) -> None:\n    loco_source = payload.pop("_loco_source_state", None)\n    gpw.validate_payload(payload, require_today=False)\n'''
m = replace_once(m, needle, insert, 'mandatory exact source')

needle2 = '    gpw.atomic_json(gpw.AUDIT_DIR / f"{payload[\'date\']}-mandatory.json", audit)\n'
insert2 = '''    gpw.atomic_json(gpw.AUDIT_DIR / f"{payload['date']}-mandatory.json", audit)\n    if isinstance(loco_source, dict):\n        gpw.atomic_json(gpw.AUDIT_DIR / f"{payload['date']}-loco-source.json", loco_source)\n'''
m = replace_once(m, needle2, insert2, 'mandatory persist source')
MANDATORY.write_text(m, encoding='utf-8')

l = LOCO.read_text(encoding='utf-8')
l = replace_once(
    l,
    '        "ranking_sha256": ranking_hash,\n        "candidates": rows,\n',
    '        "ranking_sha256": ranking_hash,\n        "producer_state_sha256": None,\n        "candidates": rows,\n',
    'loco source lineage field',
)

old_capture = '''    decision_at = _parse_dt(payload.get("generated_at"))\n    if decision_at is None:\n        return {"status": "NOT_APPLICABLE", "reason": "invalid producer timestamp"}\n    delay = (now_local.astimezone(timezone.utc) - decision_at).total_seconds()\n    if delay < -60 or delay > MAX_CAPTURE_DELAY_SECONDS:\n        return {"status": "SKIPPED_LATE_CAPTURE", "capture_delay_seconds": round(delay, 3)}\n    selection = payload.get("selection") if isinstance(payload.get("selection"), Mapping) else {}\n    if selection.get("selection_mode") != "MANDATORY_DAILY_FINAL":\n        return {"status": "UNSUPPORTED_SELECTION_MODE", "selection_mode": selection.get("selection_mode")}\n\n    decision_key = _sha({"decision_at": payload.get("generated_at"), "symbol": selection.get("symbol")})[:16]\n    path = snapshot_dir / f"{payload.get('date')}_{decision_key}.json"\n    if path.exists():\n        existing = gpw.load_json(path)\n        if not isinstance(existing, Mapping):\n            raise ValueError("existing LOCO snapshot is invalid")\n        verify_snapshot(existing)\n        return {"status": "EXISTS", "path": str(path.relative_to(ROOT)), "snapshot_status": existing.get("status")}\n\n    config = gpw.load_config()\n    policy = mandatory.load_policy()\n    market_cache = dict(cache) if cache is not None else provider.prefetch_market(config)\n    evaluated, errors = _evaluate_current_state(\n        payload=payload,\n        now=now_local,\n        config=config,\n        policy=policy,\n        cache=market_cache,\n        opening_fetcher=opening_fetcher,\n    )\n    ranking = gpw.load_json(ROOT / "data/investments/gpw_daily_candidate_ranking.json", {})\n    ranking_hash = _sha(ranking) if isinstance(ranking, Mapping) else None\n    snapshot = build_prospective_snapshot(\n        payload=payload,\n        evaluated_candidates=evaluated,\n        config=config,\n        policy=policy,\n        candidate_errors=errors,\n        captured_at=now_local,\n        ranking_hash=ranking_hash,\n    )\n'''
new_capture = '''    decision_at = _parse_dt(payload.get("generated_at"))\n    if decision_at is None:\n        return {"status": "NOT_APPLICABLE", "reason": "invalid producer timestamp"}\n    selection = payload.get("selection") if isinstance(payload.get("selection"), Mapping) else {}\n    if selection.get("selection_mode") != "MANDATORY_DAILY_FINAL":\n        return {"status": "UNSUPPORTED_SELECTION_MODE", "selection_mode": selection.get("selection_mode")}\n\n    # The complete downstream candidate state must come from the same run that\n    # made the production decision.  Never recreate it from later market data.\n    producer_state_path = gpw.AUDIT_DIR / f"{payload.get('date')}-loco-source.json"\n    producer_state = gpw.load_json(producer_state_path)\n    if not isinstance(producer_state, Mapping):\n        return {"status": "MISSING_PROSPECTIVE_PRODUCER_STATE", "reason": "same-run LOCO source was not persisted"}\n    if producer_state.get("schema_version") != "gpw-loco-producer-state-v1":\n        raise ValueError("LOCO producer state schema mismatch")\n    if str(producer_state.get("producer_decision_at") or "") != str(payload.get("generated_at") or ""):\n        raise ValueError("LOCO producer state timestamp does not match public decision")\n    if str(producer_state.get("producer_selected_symbol") or "") != str(selection.get("symbol") or ""):\n        raise ValueError("LOCO producer state selected symbol does not match public decision")\n    source_capture_at = _parse_dt(producer_state.get("captured_at"))\n    if source_capture_at is None:\n        raise ValueError("LOCO producer state capture timestamp is invalid")\n\n    decision_key = _sha({"decision_at": payload.get("generated_at"), "symbol": selection.get("symbol")})[:16]\n    path = snapshot_dir / f"{payload.get('date')}_{decision_key}.json"\n    if path.exists():\n        existing = gpw.load_json(path)\n        if not isinstance(existing, Mapping):\n            raise ValueError("existing LOCO snapshot is invalid")\n        verify_snapshot(existing)\n        return {"status": "EXISTS", "path": str(path.relative_to(ROOT)), "snapshot_status": existing.get("status")}\n\n    config = gpw.load_config()\n    policy = mandatory.load_policy()\n    evaluated = producer_state.get("candidates") if isinstance(producer_state.get("candidates"), Sequence) else []\n    errors = producer_state.get("candidate_errors") if isinstance(producer_state.get("candidate_errors"), Mapping) else {}\n    ranking = gpw.load_json(ROOT / "data/investments/gpw_daily_candidate_ranking.json", {})\n    ranking_hash = _sha(ranking) if isinstance(ranking, Mapping) else None\n    snapshot = build_prospective_snapshot(\n        payload=payload,\n        evaluated_candidates=evaluated,\n        config=config,\n        policy=policy,\n        candidate_errors=errors,\n        captured_at=source_capture_at,\n        ranking_hash=ranking_hash,\n    )\n    snapshot_body = dict(snapshot)\n    snapshot_body.pop("snapshot_sha256", None)\n    snapshot_body["producer_state_sha256"] = _sha(producer_state)\n    snapshot_body["persisted_at"] = now_local.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")\n    snapshot_body["snapshot_sha256"] = _sha(snapshot_body)\n    snapshot = snapshot_body\n    verify_snapshot(snapshot)\n'''
l = replace_once(l, old_capture, new_capture, 'loco exact capture')
LOCO.write_text(l, encoding='utf-8')

print('PR507_EXACT_CAPTURE_PATCH_OK')
